INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6cf-7a9b-9f18-e58a5e6ec9c6'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.', '16', 'Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.', 'Easy', '{"tags":"data,statistics,cumulative-frequency","subtopic":"interquartile range","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.871Z'::timestamptz, '2026-07-26T12:42:25.871Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6d7-71fb-a11b-81d02558f9ed'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).', '(4x - 4)/(x^2 - 4)', 'The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).', 'Medium', '{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.879Z'::timestamptz, '2026-07-26T12:42:25.879Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9e72-b6d9-7ffe-bda0-9c483c9a0e0b'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Expand and simplify (2x - 5)(x + 4).', '2x^2 + 3x - 20', 'Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.', 'Easy', '{"tags":"algebra,expansion,brackets","subtopic":"expansion","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T12:42:25.881Z'::timestamptz, '2026-07-26T12:42:25.881Z'::timestamptz) ON CONFLICT (id) DO NOTHING;